module:
module adder4 (input [3:0] a, input [3:0] b, input cin, output [3:0] sum, output cout);
  assign {cout, sum} = a + b + cin;
endmodule

module adder8 (input [7:0] a, input [7:0] b, output [8:0] sum);
  assign sum = a + b;
endmodule

module sub8 (input [7:0] a, input [7:0] b, output [7:0] diff, output borrow);
  assign {borrow, diff} = {1'b0, a} - b;
endmodule

module cmp8 (input [7:0] a, input [7:0] b, output eq, output lt, output gt);
  assign eq = (a == b);
  assign lt = (a < b);
  assign gt = (a > b);
endmodule

module mux2 (input [7:0] a, input [7:0] b, input sel, output [7:0] out);
  assign out = sel ? b : a;
endmodule

module mux4 (input [7:0] a, input [7:0] b, input [7:0] c, input [7:0] d, input [1:0] sel, output [7:0] out);
  assign out = (sel == 2'd0) ? a : (sel == 2'd1) ? b :
                (sel == 2'd2) ? c : d;
endmodule

module prio_encoder (input [7:0] in, output reg [2:0] code, output valid);
  always @(*) begin
    code = 3'd0;
    if (in[7]) code = 3'd7; else if (in[6]) code = 3'd6;
    else if (in[5]) code = 3'd5; else if (in[4]) code = 3'd4;
    else if (in[3]) code = 3'd3; else if (in[2]) code = 3'd2;
    else if (in[1]) code = 3'd1; else if (in[0]) code = 3'd0;
  end
  assign valid = |in;
endmodule

module decoder38 (input [2:0] in, input en, output [7:0] out);
  assign out = en ? (8'b1 << in) : 8'b0;
endmodule

module parity8 (input [7:0] data, output parity);
  assign parity = ^data;
endmodule

module alu4 (input [3:0] a, input [3:0] b, input [2:0] op, output reg [3:0] result);
  always @(*) case (op)
    3'd0: result = a + b;
    3'd1: result = a - b;
    3'd2: result = a & b;
    3'd3: result = a | b;
    3'd4: result = a ^ b;
    3'd5: result = (a < b) ? 4'd1 : 4'd0;
    3'd6: result = (a == b) ? 4'd1 : 4'd0;
    default: result = ~a;
  endcase
endmodule

module barrel8 (input [7:0] data, input [2:0] amt, input dir, output [7:0] out);
  assign out = dir ? (data >> amt) : (data << amt);
endmodule

module gray_enc (input [3:0] bin, output [3:0] gray);
  assign gray = bin ^ (bin >> 1);
endmodule

module gray_dec (input [3:0] gray, output [3:0] bin);
  assign bin[3] = gray[3];
  assign bin[2] = gray[3] ^ gray[2];
  assign bin[1] = gray[3] ^ gray[2] ^ gray[1];
  assign bin[0] = gray[3] ^ gray[2] ^ gray[1] ^ gray[0];
endmodule

module bcd_add (input [3:0] a, input [3:0] b, input cin, output [3:0] sum, output cout);
  wire [4:0] t = a + b + cin;
  assign cout = (t > 9);
  assign sum = cout ? (t - 10) : t[3:0];
endmodule

module popcount16 (input [15:0] data, output reg [4:0] count);
  integer i;
  always @(*) begin
    count = 5'd0;
    for (i = 0; i < 16; i = i + 1) count = count + data[i];
  end
endmodule

module therm3 (input [2:0] in, output [6:0] out);
  assign out = (7'd1 << in) - 7'd1;
endmodule

module neg8 (input [7:0] a, output [7:0] neg);
  assign neg = ~a + 8'd1;
endmodule

module mul4 (input [3:0] a, input [3:0] b, output [7:0] prod);
  assign prod = a * b;
endmodule

module absdiff8 (input [7:0] a, input [7:0] b, output [7:0] diff);
  assign diff = (a >= b) ? (a - b) : (b - a);
endmodule

module maj3 (input a, input b, input c, output y);
  assign y = (a & b) | (b & c) | (a & c);
endmodule

module counter8 (input clk, input rst, input en, output reg [7:0] count);
  always @(posedge clk) begin
    if (rst) count <= 8'd0;
    else if (en) count <= count + 8'd1;
  end
endmodule

module load_counter8 (input clk, input rst, input load, input [7:0] data, output reg [7:0] count);
  always @(posedge clk) begin
    if (rst) count <= 8'd0;
    else if (load) count <= data;
    else count <= count + 8'd1;
  end
endmodule

module bcd_counter (input clk, input rst, input en, output reg [3:0] count, output tc);
  always @(posedge clk) begin
    if (rst) count <= 4'd0;
    else if (en) count <= (count == 4'd9) ? 4'd0 : count + 4'd1;
  end
  assign tc = (count == 4'd9);
endmodule

module updown8 (input clk, input rst, input en, input up, output reg [7:0] count);
  always @(posedge clk) begin
    if (rst) count <= 8'd0;
    else if (en) count <= up ? count + 8'd1 : count - 8'd1;
  end
endmodule

module lfsr4 (input clk, input rst, input en, output [3:0] state);
  reg [3:0] s;
  always @(posedge clk) begin
    if (rst) s <= 4'd1;
    else if (en) s <= {s[2:0], s[3] ^ s[2]};
  end
  assign state = s;
endmodule

module shifter8 (input clk, input rst, input en, input dir, input sin, output reg [7:0] q);
  always @(posedge clk) begin
    if (rst) q <= 8'd0;
    else if (en) q <= dir ? {sin, q[7:1]} : {q[6:0], sin};
  end
endmodule

module piso8 (input clk, input rst, input load, input [7:0] data, input shift_en, output sout);
  reg [7:0] sr;
  always @(posedge clk) begin
    if (rst) sr <= 8'd0;
    else if (load) sr <= data;
    else if (shift_en) sr <= {sr[6:0], 1'b0};
  end
  assign sout = sr[7];
endmodule

module sipo8 (input clk, input rst, input en, input sin, output reg [7:0] q);
  always @(posedge clk) begin
    if (rst) q <= 8'd0;
    else if (en) q <= {q[6:0], sin};
  end
endmodule

module acc8 (input clk, input rst, input en, input [7:0] data, output reg [15:0] acc);
  always @(posedge clk) begin
    if (rst) acc <= 16'd0;
    else if (en) acc <= acc + data;
  end
endmodule

module ram16x8 (input clk, input we, input [3:0] addr, input [7:0] wdata, output [7:0] rdata);
  reg [7:0] mem [0:15];
  always @(posedge clk) begin
    if (we) mem[addr] <= wdata;
  end
  assign rdata = mem[addr];
endmodule

module fifo8x8 (input clk, input rst, input push, input pop, input [7:0] din, output [7:0] dout, output full, output empty);
  reg [7:0] mem [0:7];
  reg [3:0] count;
  reg [2:0] wp, rp;
  wire do_push = push & ~full;
  wire do_pop  = pop  & ~empty;
  assign full  = (count == 8);
  assign empty = (count == 0);
  assign dout  = mem[rp];
  always @(posedge clk) begin
    if (rst) begin count <= 4'd0; wp <= 3'd0; rp <= 3'd0; end
    else begin
      if (do_push) begin mem[wp] <= din; wp <= wp + 3'd1; end
      if (do_pop) rp <= rp + 3'd1;
      if (do_push & ~do_pop) count <= count + 4'd1;
      else if (do_pop & ~do_push) count <= count - 4'd1;
    end
  end
endmodule

module clkdiv10 (input clk, input rst, output clk_out);
  reg [3:0] cnt;
  always @(posedge clk) begin
    if (rst) cnt <= 4'd0;
    else cnt <= (cnt == 4'd9) ? 4'd0 : cnt + 4'd1;
  end
  assign clk_out = (cnt < 5);
endmodule

module pulse_stretch4 (input clk, input rst, input pulse, output stretched);
  reg [2:0] cnt;
  always @(posedge clk) begin
    if (rst) cnt <= 3'd0;
    else if (pulse) cnt <= 3'd4;
    else if (cnt > 0) cnt <= cnt - 3'd1;
  end
  assign stretched = pulse | (cnt > 0);
endmodule

module counter8_tc (input clk, input rst, input en, input [7:0] max, output reg [7:0] count, output tc);
  always @(posedge clk) begin
    if (rst) count <= 8'd0;
    else if (en) count <= (count == max) ? 8'd0 : count + 8'd1;
  end
  assign tc = (count == max);
endmodule

module ring4 (input clk, input rst, input en, output reg [3:0] q);
  always @(posedge clk) begin
    if (rst) q <= 4'b0001;
    else if (en) q <= {q[0], q[3:1]};
  end
endmodule

module johnson4 (input clk, input rst, output reg [3:0] q);
  always @(posedge clk) begin
    if (rst) q <= 4'd0;
    else q <= {~q[0], q[3:1]};
  end
endmodule

module counter4_arst (input clk, input rst, output reg [3:0] count);
  always @(posedge clk or posedge rst) begin
    if (rst) count <= 4'd0;
    else count <= count + 4'd1;
  end
endmodule

module counter4_cout (input clk, input rst, input en, output reg [3:0] count, output reg cout);
  always @(posedge clk) begin
    if (rst) begin count <= 4'd0; cout <= 1'b0; end
    else if (en) begin
      count <= count + 4'd1;
      cout <= (count == 4'd15);
    end
  end
endmodule

module sat_counter4 (input clk, input rst, input en, input up, output reg [3:0] count);
  always @(posedge clk) begin
    if (rst) count <= 4'd0;
    else if (en) begin
      if (up) count <= (count == 4'd15) ? 4'd15 : count + 4'd1;
      else count <= (count == 4'd0) ? 4'd0 : count - 4'd1;
    end
  end
endmodule

module edge_detect (input clk, input rst, input sig, output reg pulse);
  reg prev;
  always @(posedge clk) begin
    if (rst) begin prev <= 1'b0; pulse <= 1'b0; end
    else begin
      prev <= sig;
      pulse <= sig & ~prev;
    end
  end
endmodule

module seqdet1101 (input clk, input rst, input din, output reg det);
  reg [1:0] state;
  localparam S0 = 2'd0, S1 = 2'd1, S2 = 2'd2, S3 = 2'd3;
  always @(posedge clk) begin
    if (rst) begin state <= S0; det <= 1'b0; end
    else begin
      case (state)
        S0: state <= din ? S1 : S0;
        S1: state <= din ? S2 : S0;
        S2: state <= din ? S2 : S3;
        S3: state <= din ? S2 : S0;
      endcase
      det <= (state == S3) && din;
    end
  end
endmodule

module seqdet1011 (input clk, input rst, input din, output reg det);
  reg [2:0] state;
  localparam S0 = 3'd0, S1 = 3'd1, S2 = 3'd2, S3 = 3'd3, S4 = 3'd4;
  always @(posedge clk) begin
    if (rst) begin state <= S0; det <= 1'b0; end
    else begin
      det <= 1'b0;
      case (state)
        S0: state <= din ? S1 : S0;
        S1: state <= din ? S1 : S2;
        S2: state <= din ? S3 : S0;
        S3: state <= din ? S4 : S0;
        S4: begin state <= din ? S1 : S0; det <= 1'b1; end
      endcase
    end
  end
endmodule

module traffic_light (input clk, input rst, output reg [5:0] lights);
  reg [1:0] phase;
  reg [2:0] t;
  always @(posedge clk) begin
    if (rst) begin phase <= 2'd0; t <= 3'd0; end
    else case (phase)
      2'd0: if (t == 3'd3) begin phase <= 2'd1; t <= 3'd0; end else t <= t + 3'd1;
      2'd1: if (t == 3'd1) begin phase <= 2'd2; t <= 3'd0; end else t <= t + 3'd1;
      2'd2: if (t == 3'd3) begin phase <= 2'd3; t <= 3'd0; end else t <= t + 3'd1;
      default: if (t == 3'd1) begin phase <= 2'd0; t <= 3'd0; end else t <= t + 3'd1;
    endcase
  end
  always @(*) case (phase)
    2'd0: lights = 6'b001100;  // NS green, EW red
    2'd1: lights = 6'b010100;  // NS yellow, EW red
    2'd2: lights = 6'b100001;  // NS red, EW green
    default: lights = 6'b100010; // NS red, EW yellow
  endcase
endmodule

module vending (input clk, input rst, input [2:0] coin, input cancel, output reg dispense, output reg [2:0] change);
  reg [2:0] sum;
  always @(posedge clk) begin
    dispense <= 1'b0;
    change <= 3'd0;
    if (rst) sum <= 3'd0;
    else if (cancel) begin change <= sum; sum <= 3'd0; end
    else if (coin != 3'd0) begin
      case (coin)
        3'b001: if (sum + 3'd1 >= 3'd5) begin dispense <= 1'b1; change <= sum + 3'd1 - 3'd5; sum <= 3'd0; end
                else sum <= sum + 3'd1;
        3'b010: if (sum + 3'd2 >= 3'd5) begin dispense <= 1'b1; change <= sum + 3'd2 - 3'd5; sum <= 3'd0; end
                else sum <= sum + 3'd2;
        3'b100: if (sum + 3'd5 >= 3'd5) begin dispense <= 1'b1; change <= sum + 3'd5 - 3'd5; sum <= 3'd0; end
                else sum <= sum + 3'd5;
        default: ;
      endcase
    end
  end
endmodule

module gray_counter4 (input clk, input rst, input en, output reg [3:0] gray);
  reg [3:0] bin;
  always @(posedge clk) begin
    if (rst) begin bin <= 4'd0; gray <= 4'd0; end
    else if (en) begin
      bin <= bin + 4'd1;
      gray <= (bin + 4'd1) ^ ((bin + 4'd1) >> 1);
    end
  end
endmodule

module arbiter_rr (input clk, input rst, input [3:0] req, output reg [3:0] grant);
  reg [1:0] last;
  reg [3:0] g;
  reg [1:0] ln;
  reg found;
  integer i;
  always @(*) begin
    g = 4'd0; ln = last; found = 1'b0;
    for (i = 0; i < 4; i = i + 1) begin
      if (req[(last + 2'd1 + i) % 4] && !found) begin
        g = 4'b1 << ((last + 2'd1 + i) % 4);
        ln = (last + 2'd1 + i) % 4;
        found = 1'b1;
      end
    end
  end
  always @(posedge clk) begin
    if (rst) begin grant <= 4'd0; last <= 2'd0; end
    else begin
      grant <= g;
      if (found) last <= ln;
    end
  end
endmodule

module uart_tx (input clk, input rst, input send, input [7:0] data, output reg tx, output reg busy);
  reg active;
  reg [3:0] bit_cnt;
  reg [3:0] bit_idx;
  reg [7:0] sr;
  always @(posedge clk) begin
    if (rst) begin tx <= 1'b1; busy <= 1'b0; active <= 1'b0; bit_cnt <= 4'd0; bit_idx <= 4'd0; sr <= 8'd0; end
    else if (!active) begin
      if (send) begin active <= 1'b1; busy <= 1'b1; sr <= data; bit_idx <= 4'd0; bit_cnt <= 4'd0; tx <= 1'b0; end
      else begin tx <= 1'b1; busy <= 1'b0; end
    end else begin
      if (bit_cnt == 4'd15) begin
        bit_cnt <= 4'd0;
        if (bit_idx == 4'd9) begin active <= 1'b0; busy <= 1'b0; tx <= 1'b1; end
        else begin
          if (bit_idx == 4'd8) tx <= 1'b1;
          else tx <= sr[bit_idx];
          bit_idx <= bit_idx + 4'd1;
        end
      end else bit_cnt <= bit_cnt + 4'd1;
    end
  end
endmodule

module uart_rx (input clk, input rst, input rx, output reg [7:0] data, output reg valid, output reg frame_err);
  localparam IDLE = 2'd0, START = 2'd1, DATA = 2'd2, STOP = 2'd3;
  reg [1:0] state;
  reg [3:0] cnt;
  reg [2:0] idx;
  always @(posedge clk) begin
    valid <= 1'b0;
    frame_err <= 1'b0;
    if (rst) begin state <= IDLE; cnt <= 4'd0; idx <= 3'd0; data <= 8'd0; end
    else case (state)
      IDLE: begin
        if (!rx) begin state <= START; cnt <= 4'd0; end
      end
      START: begin
        if (cnt == 4'd7) begin
          if (!rx) begin state <= DATA; cnt <= 4'd0; idx <= 3'd0; end
          else state <= IDLE;
        end else cnt <= cnt + 4'd1;
      end
      DATA: begin
        if (cnt == 4'd15) begin
          cnt <= 4'd0;
          if (idx == 3'd7) state <= STOP;
          else idx <= idx + 3'd1;
        end else if (cnt == 4'd8) begin data[idx] <= rx; cnt <= cnt + 4'd1; end
        else cnt <= cnt + 4'd1;
      end
      STOP: begin
        if (cnt == 4'd15) begin state <= IDLE; cnt <= 4'd0; valid <= 1'b1; end
        else begin
          if (cnt == 4'd8) frame_err <= ~rx;
          cnt <= cnt + 4'd1;
        end
      end
    endcase
  end
endmodule

module seqdet1001 (input clk, input rst, input din, output reg det);
  reg [1:0] state;
  localparam S0 = 2'd0, S1 = 2'd1, S2 = 2'd2, S3 = 2'd3;
  always @(posedge clk) begin
    if (rst) begin state <= S0; det <= 1'b0; end
    else begin
      case (state)
        S0: state <= din ? S1 : S0;
        S1: state <= din ? S1 : S2;
        S2: state <= din ? S1 : S3;
        S3: state <= din ? S1 : S0;
      endcase
      det <= (state == S3) && din;
    end
  end
endmodule

module garage_counter (input clk, input rst, input car_enter, input car_exit, output reg [3:0] count, output full, output empty);
  always @(posedge clk) begin
    if (rst) count <= 4'd0;
    else begin
      if (car_enter & ~car_exit & (count < 4'd15)) count <= count + 4'd1;
      else if (car_exit & ~car_enter & (count > 4'd0)) count <= count - 4'd1;
    end
  end
  assign full = (count == 4'd15);
  assign empty = (count == 4'd0);
endmodule

module handshake (input clk, input rst, input req, output reg ack, output reg pulse);
  reg state;
  localparam IDLE = 1'b0, ACK_HIGH = 1'b1;
  always @(posedge clk) begin
    pulse <= 1'b0;
    if (rst) begin state <= IDLE; ack <= 1'b0; end
    else case (state)
      IDLE: if (req) begin state <= ACK_HIGH; ack <= 1'b1; end
      ACK_HIGH: if (!req) begin state <= IDLE; ack <= 1'b0; pulse <= 1'b1; end
    endcase
  end
endmodule

module debouncer4 (input clk, input rst, input btn, output reg stable);
  reg [1:0] cnt;
  reg prev;
  always @(posedge clk) begin
    if (rst) begin cnt <= 2'd0; prev <= 1'b0; stable <= 1'b0; end
    else begin
      prev <= btn;
      if (btn != prev) cnt <= 2'd0;
      else if (cnt < 2'd3) cnt <= cnt + 2'd1;
      // 非阻塞语义：此处读到的是更新前的 cnt——旧值 2 表示
      // 本拍是第 4 个连续相同电平（首拍 + 3 拍重复）
      if (btn == prev && cnt == 2'd2) stable <= btn;
    end
  end
endmodule
